package com.hellodoc.dto;
import com.hellodoc.entity.Doctor; import java.util.*;
public record DoctorSearchDto(UUID id,String firstName,String lastName,String fullName,String serviceTitle,String specialty,String city,String location,String address,String status,java.time.Instant nextAvailability) { public static DoctorSearchDto from(Doctor d,java.time.Instant nextAvailability){var u=d.getUser();String full=u.getFirstName()+" "+u.getLastName();String specialty=d.getSpecialties().stream().map(s->s.getName()).sorted().findFirst().orElse("");return new DoctorSearchDto(d.getId(),u.getFirstName(),u.getLastName(),full,d.getServiceTitle(),specialty,d.getCity(),d.getLocation(),d.getAddress(),"ACTIVE",nextAvailability);} public static DoctorSearchDto from(Doctor d){return from(d,null);} }
